                              "Start": 0,
                              "Length": 22,
                              "Type": "Bold"
                            }
                          ]
                        },
                        {
                          "String": "Nephrotoxic drugs: Concurrent administration of mannitol and nephrotoxic drugs, including aminoglycosides and diuretics, should be avoided due to the potential for nephrotoxicity.",
                          "Markup": [
                            {
                              "Start": 0,
                              "Length": 18,
                              "Type": "Bold"
                            },
