                              "Type": "PubChem Internal Link",
                              "Extra": "CID-6251"
                            }
                          ]
                        },
                        {
                          "String": "Neurotoxic Drugs: Concurrent administration of neurotoxic drugs may exacerbate the CNS toxicity associated with mannitol and should be avoided.",
                          "Markup": [
